import sympy
from sympy import I, exp, pi, Matrix, zeros, simplify, sqrt

def solve():
    n = 13
    # A is 12x12
    # A_{kr} = 1 if (k=r) or (k=r-1 mod 13 and k!=0) or (k=r+1 mod 13 and k!=0)
    # k, r in {1..12}
    A = zeros(n - 1, n - 1)
    for r in range(1, n):
        for k in range(1, n):
            neighbors = {r, (r - 1) % n, (r + 1) % n}
            if k in neighbors and k != 0:
                A[k - 1, r - 1] = 1

    # We want to find the image of A over GF(2).
    # Convert A to a matrix over GF(2)
    mat = A.copy()
    rows, cols = mat.shape
    pivot_cols = []
    curr_row = 0
    for col in range(cols):
        for row in range(curr_row, rows):
            if mat[row, col] % 2 == 1:
                mat.row_swap(curr_row, row)
                for r in range(rows):
                    if r != curr_row and mat[r, col] % 2 == 1:
                        mat[r, :] = (mat[r, :] - mat[curr_row, :]) % 2
                pivot_cols.append(col)
                curr_row += 1
                break

    basis = [A[:, c] for c in pivot_cols]

    max_val_sq = 0
    import itertools
    for coeffs in itertools.product([0, 1], repeat=len(basis)):
        u = zeros(n - 1, 1)
        for i, c in enumerate(coeffs):
            if c == 1:
                u = (u + basis[i]) % 2

        # s = 1 + sum_{k=1..12} u_{k-1} * exp(2*pi*I*k/13)
        s_val = 1
        for k in range(1, n):
            if u[k - 1] == 1:
                s_val += exp(2 * pi * I * k / 13)

        # Calculate |s|^2
        val_sq = simplify(s_val * s_val.conjugate())
        if val_sq > max_val_sq:
            max_val_sq = val_sq

    return sqrt(max_val_sq)

ans = solve()
print(f"ANSWER: {sympy.latex(ans)}")
